def gain_summary(values):
 active=[r for r in values if r['teacher_rms']>=1e-3 and r['student_rms']>0]
 computed=[]
 for r in active:
  c=max(-1.,min(1.,r['waveform_cosine']));a=r['student_rms']/r['teacher_rms']
  g=c/a;gp=max(0,g)
  before=max(0,1+a*a-2*a*c);after=max(0,1+a*a*gp*gp-2*a*c*gp)
  computed.append(dict(source_id=r['source_id'], start_frame=r['start_frame'],condition=metadata[r['source_id']]['condition'],cosine=c,amplitude_ratio=a,
   optimal_signed_gain=g,optimal_nonnegative_gain=gp,
   amplitude_matching_gain=1/a,
   original_relative_mse=before,best_scalar_relative_mse=after,
   relative_mse_reduction_fraction=1-after/before if before else 0))
 return {'active_crops':len(active),'optimal_signed_gain':stats(v['optimal_signed_gain'] for v in computed),
  'optimal_nonnegative_gain':stats(v['optimal_nonnegative_gain'] for v in computed),
  'amplitude_matching_gain':stats(v['amplitude_matching_gain'] for v in computed),
  'relative_mse_before':stats(v['original_relative_mse'] for v in computed),
  'relative_mse_after_best_nonnegative_gain':stats(v['best_scalar_relative_mse'] for v in computed),
  'mse_reduction_fraction':stats(v['relative_mse_reduction_fraction'] for v in computed),
  'best_gain_between_0_8_and_1_2':sum(.8<=v['optimal_nonnegative_gain']<=1.2 for v in computed),
  'best_gain_below_1':sum(v['optimal_nonnegative_gain']<1 for v in computed),
  'rows':computed}

